import {escapeHTML as e,mediaURL,cover} from './shared.js';
export function picture(m,base,cls='',eager=false){return m?`<img class="${cls}" src="${e(mediaURL(m.src,base))}" srcset="${e(mediaURL(m.thumb,base))} 560w, ${e(mediaURL(m.src,base))} 1920w" sizes="(max-width:700px) 100vw, 65vw" alt="${e(m.alt)}" loading="${eager?'eager':'lazy'}" decoding="async">`:'<div class="empty-art">A new perspective.</div>';}
export function card(p,base,i=0){return `<a class="project-card" href="${base}projects/${e(p.slug)}/"><div class="card-image">${picture(cover(p),base,'',i<2)}<span class="round-arrow" aria-hidden="true">↗</span></div><div class="card-caption"><div><small>${e(p.category)}${p.demo?' · CONCEPT STUDY':''}</small><h3>${e(p.title)}</h3><p>${e(p.subtitle)}</p></div><span>${e(p.date?.slice(0,4))}</span></div></a>`;}
export function detail(p,base){return `<section class="detail-head"><a class="eyebrow" href="${base}projects/">← All projects</a><div class="detail-title"><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p></div><div class="project-meta"><span>${e(p.category)}</span><span>${e(p.date?.slice(0,4))}</span><span>${e(p.role||'')}</span></div>${p.demo?'<p class="concept-note">Independent concept study · Not commissioned client work</p>':''}</section>${picture(cover(p),base,'detail-cover',true)}<section class="story"><span class="eyebrow">THE IDEA</span><p>${e(p.description)}</p></section><div class="gallery-public">${p.gallery.filter(m=>m.id!==p.cover).map(m=>`<figure>${picture(m,base)}<figcaption>${e(m.alt)}</figcaption></figure>`).join('')}</div>`;}
export function shell({site,base,title,body,active='',canonical='',script=''}){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="${e(site.description)}"><meta name="theme-color" content="#f2efe9"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' https: blob: data:; connect-src 'self' https://api.github.com; object-src 'none'; base-uri 'self'; form-action 'self'"><title>${e(title)} — ${e(site.name)}</title>${canonical?`<link rel="canonical" href="${e(canonical)}"><meta property="og:url" content="${e(canonical)}">`:''}<meta property="og:title" content="${e(title)} — ${e(site.name)}"><meta property="og:description" content="${e(site.description)}"><link rel="icon" href="${base}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="${base}assets/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="wordmark" href="${base}">${e(site.name)}<span class="brand-star">✳</span></a><nav aria-label="Main navigation">${[['projects','Work'],['about','About'],['contact','Contact']].map(([url,label])=>`<a ${active===url?'aria-current="page"':''} href="${base}${url}/">${label}</a>`).join('')}</nav></header><main id="main">${body}</main><footer class="site-footer"><a class="wordmark" href="${base}">${e(site.name)} <span>✳</span></a><p>${e(site.role)}</p><a href="${base}contact/">Start a conversation ↗</a><div class="social-links">${(site.socials||[]).map(l=>`<a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${e(l.label)} ↗</a>`).join('')}</div><small>© ${new Date().getFullYear()} ${e(site.name)}</small></footer>${script?`<script type="module" src="${base}assets/${script}"></script>`:''}</body></html>`;}
